<?php require APPPATH.'views/admin/includes/native_company_layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'tickets/ai');$target=$url.($ticket?'?ticket='.$ticket.'&operation='.$operation:'');$hidden=function($action)use($esc,$csrf,$profile){?><input type="hidden" name="company_ai_csrf" value="<?= $esc($csrf); ?>"><input type="hidden" name="revision" value="<?= $profile['revision']; ?>"><input type="hidden" name="action" value="<?= $esc($action); ?>"><?php }; ?>
<section class="company-settings-card"><h1>Assistente privado da empresa</h1><p>OpenAI com chave própria. Cadastro não comprova acesso ao modelo nem entrega externa. Resumos e sugestões permanecem privados para quem solicitou; nunca respondem ao cliente ou publicam no portal.</p><p>Estado: <strong id="ai-status" data-status="<?= $esc($profile['status']); ?>"><?= $esc(['absent'=>'Sem credenciais próprias','configured'=>'Credenciais próprias cadastradas','revoked'=>'Conexão local revogada'][$profile['status']]??'Indisponível'); ?></strong>.</p><?php if($error){?><p role="alert"><?= $esc($error); ?></p><?php } ?>
<?php if($can_configure){?><?= form_open($url,['id'=>'ai-profile']);$hidden('save'); ?><label for="ai-model">Modelo</label><select id="ai-model" name="model"><?php foreach(CompanyAi::models()as$id=>$label){?><option value="<?= $esc($id); ?>"<?= $profile['model']===$id?' selected':''; ?>><?= $esc($label); ?></option><?php } ?></select><label for="ai-secret">Nova chave própria</label><input id="ai-secret" type="password" name="secret" value="" autocomplete="new-password" maxlength="4096" required><label><input type="checkbox" name="operations[]" value="summary"<?= in_array('summary',$profile['operations'],true)?' checked':''; ?>>Permitir resumo revisado</label><label><input type="checkbox" name="operations[]" value="reply"<?= in_array('reply',$profile['operations'],true)?' checked':''; ?>>Permitir sugestão revisada</label><button type="submit">Salvar credenciais próprias</button><?= form_close(); ?><?php if($profile['revision']){?><?= form_open($url,['id'=>'ai-revoke']);$hidden('revoke'); ?><button type="submit">Revogar conexão local</button><?= form_close(); ?><?php }} ?>
<form method="get" action="<?= $esc($url); ?>" id="ai-select"><label for="ai-ticket">Chamado próprio</label><input type="number" id="ai-ticket" name="ticket" min="1" max="999999999" required value="<?= $ticket?:''; ?>"><label for="ai-operation">Ação</label><select id="ai-operation" name="operation"><option value="summary"<?= $operation==='summary'?' selected':''; ?>>Resumo privado</option><option value="reply"<?= $operation==='reply'?' selected':''; ?>>Sugestão privada de resposta</option></select><button type="submit">Revisar conteúdo</button></form>
<?php if($preview){?><h2>Conteúdo exato da solicitação</h2><p>Limite de 12.000 bytes e 20 respostas. O conteúdo abaixo será incluído como dados, junto da instrução fixa de <?= $operation==='summary'?'resumo':'sugestão de resposta'; ?>. Não inclui arquivos, contatos, sessão ou credenciais. Respostas podem estar incorretas; revise antes de usar.</p><pre id="ai-preview"><?= $esc(json_encode($preview['input'],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)); ?></pre><?= form_open($target,['id'=>'ai-queue']);$hidden('queue'); ?><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(32)); ?>"><input type="hidden" name="source_hash" value="<?= $esc($preview['source_hash']); ?>"><label><input type="checkbox" name="consent" value="1" required>Autorizo esta ação e o envio desse conteúdo ao provedor desta empresa. Pode haver cobrança.</label><button type="submit">Registrar intenção local</button><?= form_close(); ?><?php } ?>
<?php if($history){?><h2>Histórico privado desta pessoa</h2><p>Registrar intenção não chama o provedor. Uma tentativa em andamento ou incerta nunca é reenviada automaticamente, mesmo com outra chave de solicitação. Mudar origem ou credenciais exige nova revisão e autorização.</p><ul id="ai-history"><?php foreach($history as$h){?><li data-ai-key="<?= $esc($h['request_key']); ?>"><span data-ai-status="<?= $esc($h['status']); ?>"><?= $esc(['pending'=>'Intenção local sem envio','submitting'=>'Tentativa em andamento; não repetir','completed'=>'Resultado privado disponível','uncertain'=>'Resultado incerto; não reenviar','forgotten'=>'Resultado local apagado','blocked'=>'Bloqueado antes do envio'][$h['status']]??'Indisponível'); ?></span> — <?= $esc($h['operation']); ?><?php if($h['status']==='pending'){?><?= form_open($target,['class'=>'ai-dispatch']);$hidden('dispatch'); ?><input type="hidden" name="request_key" value="<?= $esc($h['request_key']); ?>"><button type="submit">Executar solicitação autorizada</button><?= form_close(); ?><?php }elseif($h['status']==='completed'){?><a class="ai-result-link" href="<?= $esc($target.'&result='.$h['request_key']); ?>">Abrir resultado privado</a><?= form_open($target,['class'=>'ai-forget']);$hidden('forget'); ?><input type="hidden" name="request_key" value="<?= $esc($h['request_key']); ?>"><button type="submit">Apagar resultado local</button><?= form_close(); ?><?php } ?></li><?php } ?></ul><?php } ?>
<?php if($result!==null){?><h2>Resultado para revisão humana</h2><pre id="ai-result"><?= $esc($result); ?></pre><?php } ?></section><?php require APPPATH.'views/admin/includes/native_company_layout_tail.php'; ?>
